  'AajExam Team': 'AajExam ਟੀਮ',
  'AajExam helps students across India prepare for government exams. We believe every student deserves good study material, no matter where they come from.': 'AajExam ਦੇਸ਼ ਭਰ ਦੇ ਵਿਦਿਆਰਥੀਆਂ ਨੂੰ ਸਰਕਾਰੀ ਪ੍ਰੀਖਿਆਵਾਂ ਦੀ ਤਿਆਰੀ ਵਿੱਚ ਮਦਦ ਕਰਦਾ ਹੈ। ਸਾਡਾ ਮੰਨਣਾ ਹੈ ਕਿ ਹਰ ਵਿਦਿਆਰਥੀ, ਭਾਵੇਂ ਉਹ ਕਿਤੋਂ ਵੀ ਆਇਆ ਹੋਵੇ, ਚੰਗੀ ਪੜ੍ਹਾਈ ਸਮੱਗਰੀ ਦਾ ਹੱਕਦਾਰ ਹੈ।',
  'AajExam is about your knowledge and your hard work. The more you study and practice, the better your score. Only your effort takes you to the top.': 'AajExam ਤੁਹਾਡੇ ਗਿਆਨ ਅਤੇ ਮਿਹਨਤ ਬਾਰੇ ਹੈ। ਜਿੰਨਾ ਜ਼ਿਆਦਾ ਤੁਸੀਂ ਪੜ੍ਹੋਗੇ ਅਤੇ ਅਭਿਆਸ ਕਰੋਗੇ, ਤੁਹਾਡਾ ਸਕੋਰ ਓਨਾ ਹੀ ਵਧੀਆ ਹੋਵੇਗਾ। ਸਿਰਫ਼ ਤੁਹਾਡੀ ਕੋਸ਼ਿਸ਼ ਹੀ ਤੁਹਾਨੂੰ ਸਿਖਰ \'ਤੇ ਲੈ ਜਾਂਦੀ ਹੈ।',
