  'Thousands of students are already studying, scoring better, and earning by inviting friends. Join them today.': 'ਹਜ਼ਾਰਾਂ ਵਿਦਿਆਰਥੀ ਪਹਿਲਾਂ ਹੀ ਪੜ੍ਹ ਰਹੇ ਹਨ, ਬਿਹਤਰ ਸਕੋਰ ਕਰ ਰਹੇ ਹਨ ਅਤੇ ਦੋਸਤਾਂ ਨੂੰ ਸੱਦਾ ਦੇ ਕੇ ਕਮਾ ਰਹੇ ਹਨ। ਅੱਜ ਹੀ ਉਨ੍ਹਾਂ ਨਾਲ ਜੁੜੋ।',
  'To become India\'s most trusted and comprehensive government exam preparation platform, empowering millions of students to achieve their career goals in public service through innovative technology and quality educational content.': 'ਨਵੀਨਤਮ ਤਕਨਾਲੋਜੀ ਅਤੇ ਮਿਆਰੀ ਵਿੱਦਿਅਕ ਸਮੱਗਰੀ ਰਾਹੀਂ ਲੱਖਾਂ ਵਿਦਿਆਰਥੀਆਂ ਨੂੰ ਲੋਕ ਸੇਵਾ ਵਿੱਚ ਆਪਣੇ ਕਰੀਅਰ ਟੀਚੇ ਪ੍ਰਾਪਤ ਕਰਨ ਲਈ ਸਮਰੱਥ ਬਣਾਉਂਦੇ ਹੋਏ, ਭਾਰਤ ਦਾ ਸਭ ਤੋਂ ਭਰੋਸੇਮੰਦ ਅਤੇ ਵਿਆਪਕ ਸਰਕਾਰੀ ਪ੍ਰੀਖਿਆ ਤਿਆਰੀ ਪਲੇਟਫਾਰਮ ਬਣਨਾ।',
  'To provide accessible, affordable, and effective exam preparation resources that combine cutting-edge technology with proven pedagogical methods. We aim to bridge the gap between traditional coaching and modern digital learning.': 'ਅਤਿ-ਆਧੁਨਿਕ ਤਕਨਾਲੋਜੀ ਨੂੰ ਪਰਖੇ ਹੋਏ ਅਧਿਆਪਨ ਢੰਗਾਂ ਨਾਲ ਜੋੜਨ ਵਾਲੇ ਪਹੁੰਚਯੋਗ, ਕਿਫਾਇਤੀ ਅਤੇ ਪ੍ਰਭਾਵਸ਼ਾਲੀ ਪ੍ਰੀਖਿਆ ਤਿਆਰੀ ਸਰੋਤ ਮੁਹੱਈਆ ਕਰਵਾਉਣਾ। ਰਵਾਇਤੀ ਕੋਚਿੰਗ ਅਤੇ ਆਧੁਨਿਕ ਡਿਜੀਟਲ ਸਿੱਖਿਆ ਵਿਚਕਾਰ ਪਾੜੇ ਨੂੰ ਪੂਰਨਾ ਸਾਡਾ ਉਦੇਸ਼ ਹੈ।',
  'Today': 'ਅੱਜ',
  'Try adjusting your filters or check back later.': 'ਆਪਣੇ ਫਿਲਟਰ ਬਦਲ ਕੇ ਦੇਖੋ ਜਾਂ ਬਾਅਦ ਵਿੱਚ ਮੁੜ ਆਓ।',
