  'Daily Challenge + streak': 'ਰੋਜ਼ਾਨਾ ਚੁਣੌਤੀ + ਸਟ੍ਰੀਕ',
  'Streak freeze (protect your streak)': 'ਸਟ੍ਰੀਕ ਫ੍ਰੀਜ਼ (ਆਪਣੀ ਸਟ੍ਰੀਕ ਬਚਾਓ)',
  '2 per week': 'ਹਫ਼ਤੇ ਵਿੱਚ 2',
  'Current affairs & exam news': 'ਕਰੰਟ ਅਫੇਅਰਜ਼ ਅਤੇ ਪ੍ਰੀਖਿਆ ਖ਼ਬਰਾਂ',
  'Exam calendar': 'ਪ੍ਰੀਖਿਆ ਕੈਲੰਡਰ',
  'Progress & analytics': 'ਤਰੱਕੀ ਅਤੇ ਵਿਸ਼ਲੇਸ਼ਣ',
  'Basic score card after each test': 'ਹਰ ਟੈਸਟ ਤੋਂ ਬਾਅਦ ਮੁੱਢਲਾ ਸਕੋਰ ਕਾਰਡ',
  'Leaderboard & rank': 'ਲੀਡਰਬੋਰਡ ਅਤੇ ਰੈਂਕ',
  'All India Rank (AIR)': 'ਆਲ ਇੰਡੀਆ ਰੈਂਕ (AIR)',
  'Performance analytics': 'ਕਾਰਗੁਜ਼ਾਰੀ ਵਿਸ਼ਲੇਸ਼ਣ',
  'Quiz & exam attempt history': 'ਕੁਇਜ਼ ਅਤੇ ਪ੍ਰੀਖਿਆ ਕੋਸ਼ਿਸ਼ ਇਤਿਹਾਸ',
  'Study tools': 'ਪੜ੍ਹਾਈ ਦੇ ਸਾਧਨ',
  'Notes & formulas': 'ਨੋਟਸ ਅਤੇ ਫਾਰਮੂਲੇ',
